#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>


namespace {

using v8::FunctionTemplate;
using v8::Local;
using v8::Object;
using v8::String;
using v8::Value;


NAN_METHOD(Socket) {
    int fd;
    int type;

    assert(info.Length() == 0);

    type = SOCK_STREAM;
    type |= SOCK_NONBLOCK | SOCK_CLOEXEC;

    fd = socket(AF_UNIX, type, 0);
    if (fd == -1) {
        fd = -errno;
        goto out;
    }

out:
    info.GetReturnValue().Set(fd);
}


NAN_METHOD(Bind) {
    sockaddr_un s;
    socklen_t namelen;
    int err;
    int fd;
    unsigned int len;

    assert(info.Length() == 2);

    fd = info[0]->Int32Value(Nan::GetCurrentContext()).FromJust();
    Nan::Utf8String path(info[1]);

    if ((*path)[0] != '\0') {
        err = -EINVAL;
        goto out;
    }

    len = path.length();
    if (len > sizeof(s.sun_path)) {
        err = -EINVAL;
        goto out;
    }

    memset(&s, 0, sizeof s);
    memcpy(s.sun_path, *path, len);
    s.sun_family = AF_UNIX;
    namelen = offsetof(struct sockaddr_un, sun_path) + len;

    err = 0;
    if (bind(fd, reinterpret_cast<sockaddr*>(&s), namelen))
        err = -errno;

out:
    info.GetReturnValue().Set(err);
}


NAN_METHOD(Connect) {
