    memcpy(s.sun_path, *path, len);
    s.sun_family = AF_UNIX;
    namelen = offsetof(struct sockaddr_un, sun_path) + len;

    err = 0;
    if (connect(fd, reinterpret_cast<sockaddr*>(&s), namelen))
